const calendar=document.querySelector('#calendar'), preview=document.querySelector('#preview'), modal=document.querySelector('#door-dialog');
const icons=[ '<path d="M20 2 10 13h6L7 23h26L24 13h6Z M20 23v6"/>', '<path d="m8 3 25 25M32 3 7 25M6 1l5 5-4 4-5-5Zm28 0-5 5 4 4 5-5Z"/>', '<path d="m20 1 3 10 10 1-8 7 3 10-8-6-8 6 3-10-8-7 10-1Z"/>', '<path d="M10 12h20v16H10ZM7 9h26v6H7ZM20 9v19M20 9C3 8 13-5 20 9Zm0 0c17-1 7-14 0 0Z"/>', '<circle cx="20" cy="16" r="10" stroke-dasharray="3 2"/><path d="m15 6 5 4 5-4M17 2h6l-3 8"/>', '<path d="M20 1v28M7 8l26 14M7 22 33 8M16 4l4 4 4-4M16 26l4-4 4 4"/>' ];
let opened=new Set(), previewOpened=new Set(), activeDoor=null, busy=false, currentYear=new Date().getFullYear();
function readProgress(){try{const v=JSON.parse(localStorage.getItem('oars-advent-'+currentYear)||'[]');opened=new Set(Array.isArray(v)?v.filter(n=>Number.isInteger(n)&&n>=1&&n<=24):[])}catch{opened=new Set()}}
readProgress();
function available(day,date=new Date()){return date.getMonth()===11&&date.getDate()>=day}
function save(){try{localStorage.setItem('oars-advent-'+currentYear,JSON.stringify([...opened]))}catch{toast('Your browser could not save progress. You can still enjoy every door.')}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500)}
function render(){const now=new Date();if(now.getFullYear()!==currentYear){currentYear=now.getFullYear();readProgress()}const progress=preview.checked?previewOpened:opened;calendar.replaceChildren();for(let day=1;day<=24;day++){const unlocked=preview.checked||available(day,now),seen=progress.has(day);const button=document.createElement('button');button.type='button';button.className='door'+(seen?' viewed':'')+(!preview.checked&&now.getMonth()===11&&now.getDate()===day?' today':'');button.dataset.day=day;button.setAttribute('aria-label',`December ${day}, ${seen?'opened':unlocked?'ready to open':'locked until December '+day}`);button.setAttribute('aria-disabled',String(!unlocked));button.innerHTML=`<span class="door-face"><span class="door-art" aria-hidden="true"><svg viewBox="0 0 40 30">${icons[(day-1)%6]}</svg></span><span class="number">${day.toString().padStart(2,'0')}</span><span class="door-label">${seen?'OPEN AGAIN':day===24?'CHRISTMAS EVE':unlocked?'UNWRAP A LITTLE JOY':'DECEMBER'}</span></span>`;button.addEventListener('click',()=>openDoor(day,button));calendar.append(button)}document.querySelector('#count').textContent=`${progress.size} / 24`;document.querySelector('#preview-note').hidden=!preview.checked;document.querySelector('#season-status').textContent=preview.checked?'A sneak peek at the Christmas magic.':now.getMonth()===11?(now.getDate()<=24?`It’s ${now.getDate()} December. Your next surprise awaits.`:'Merry Christmas, crew! All 24 doors are ready.'):'The countdown begins on 1 December.'}
function openDoor(day,button){if(busy)return;if(!preview.checked&&!available(day)){toast(`A little patience, crew. This door opens on ${day} December.`);return}busy=true;activeDoor=day;button.classList.add('open');const content=window.ADVENT_CONTENT.find(item=>item.day===day)||{title:'Coming soon',body:'Your coach’s surprise will be here soon.'};document.querySelector('#modal-day').textContent=`DECEMBER ${day} · ${preview.checked?'PREVIEW':'FOR THE CREW'}`;document.querySelector('#modal-title').textContent=content.title;document.querySelector('#modal-body').textContent=content.body;const link=document.querySelector('#modal-link');link.hidden=true;link.removeAttribute('href');try{const url=new URL(content.link);if(url.protocol==='https:'){link.href=url.href;link.hidden=false}}catch{}(preview.checked?previewOpened:opened).add(day);if(!preview.checked)save();setTimeout(()=>{modal.showModal();busy=false},matchMedia('(prefers-reduced-motion: reduce)').matches?0:650)}
modal.addEventListener('close',()=>{render();calendar.querySelector(`[data-day="${activeDoor}"]`)?.focus()});
for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()}})}
document.querySelector('#back').onclick=()=>modal.close();document.querySelector('#about').onclick=()=>document.querySelector('#info-dialog').showModal();document.querySelector('#got-it').onclick=()=>document.querySelector('#info-dialog').close();preview.onchange=render;document.querySelector('#reset').onclick=()=>{if(confirm(`Reset your ${preview.checked?'preview':'December'} opened-door progress on this device?`)){if(preview.checked)previewOpened.clear();else{opened.clear();save()}render();toast('Your calendar is ready for a fresh start.')}};
setInterval(()=>{if(!modal.open&&!busy)render()},60000);render();
